\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For self-avoiding walk in dimensions $d=2$ and $d=3$, prove that there exists $\varepsilon>0$ such that

$$n^{2/d+\varepsilon}\leq \mathbb E_n[\operatorname{Dist}(\gamma_n,0)^2]\leq n^{2-\varepsilon}$$

for all sufficiently large $n$.
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2013/18}{[S2]}.

\subsection{Short English statement}
For self-avoiding walk in dimensions $d=2$ and $d=3$, prove that there exists $\varepsilon>0$ such that

$$n^{2/d+\varepsilon}\leq \mathbb E_n[\operatorname{Dist}(\gamma_n,0)^2]\leq n^{2-\varepsilon}$$

for all sufficiently large $n$.

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30002319 (OWR-12481-004). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2013/18}.
\end{itemize}
\label{end:30002319}

